{
  "$schema": "https://open-design.ai/schemas/plugin.v1.json",
  "specVersion": "1.0.0",
  "name": "example-html-ppt-presenter-mode-reveal",
  "title": "Html Ppt Presenter Mode Reveal",
  "title_i18n": {
    "zh-CN": "Html Ppt 演讲者模式 Reveal",
    "zh-TW": "Html Ppt 演講者模式 Reveal",
    "ja": "Html Ppt プレゼンターモード Reveal",
    "ko": "Html Ppt 발표자 모드 Reveal",
    "de": "Html Ppt Präsentationsmodus Reveal",
    "fr": "Html Ppt Mode Présentateur Reveal",
    "ru": "Html Ppt Режим Докладчика Reveal",
    "es": "Html Ppt Modo Presentador Reveal",
    "pt-BR": "Html Ppt Modo Apresentador Reveal",
    "it": "Html Ppt Modalità Relatore Reveal",
    "vi": "Html Ppt Chế Độ Diễn Giả Reveal",
    "pl": "Html Ppt Tryb Prezentera Reveal",
    "id": "Html Ppt Mode Presenter Reveal",
    "nl": "Html Ppt Presentatormodus Reveal",
    "ar": "Html Ppt وضع المقدم Reveal",
    "tr": "Html Ppt Sunucu Modu Reveal",
    "uk": "Html Ppt Режим Доповідача Reveal",
    "en": "Html Ppt Presenter Mode Reveal"
  },
  "version": "0.1.0",
  "description": "演讲者模式专用 deck — tokyo-night 默认主题，5 套主题 T 键切换，每页带 150-300 字逐字稿示例（<aside class=\"notes\">），按 S 打开 popup（CURRENT / NEXT / SCRIPT / TIMER 四张磁吸卡片）。用于技术分享、公开演讲、课程讲解，怕忘词或要提词器的场景。",
  "description_i18n": {
    "zh-CN": "演讲者模式专用 deck — tokyo-night 默认主题，5 套主题 T 键切换，每页带 150-300 字逐字稿示例（<aside class=\"notes\">），按 S 打开 popup（CURRENT / NEXT / SCRIPT / TIMER 四张磁吸卡片）。用于技术分享、公开演讲、课程讲解，怕忘词或要提词器的场景。",
    "zh-TW": "演講者模式專用 deck — tokyo-night 預設主題，5 套主題 T 鍵切換，每頁帶 150-300 字逐字稿範例（<aside class=\"notes\">），按 S 開啟 popup（CURRENT / NEXT / SCRIPT / TIMER 四張磁吸卡片）。用於技術分享、公開演講、課程講解，怕忘詞或要提詞器的場景。",
    "ja": "プレゼンターモード専用デッキ — tokyo-night デフォルトテーマ、T キーで切り替え可能な 5 つのテーマ、各ページに 150-300 字の詳細スクリプト例（<aside class=\"notes\">）、S キーで popup を開く（CURRENT / NEXT / SCRIPT / TIMER の 4 枚のカード）。技術共有、公開スピーチ、授業での使用に最適。",
    "ko": "발표자 모드 전용 deck — tokyo-night 기본 테마, T 키로 전환 가능한 5가지 테마, 각 페이지에 150-300자 스크립트 예제（<aside class=\"notes\">）, S 키로 popup 열기（CURRENT / NEXT / SCRIPT / TIMER 4개 카드）. 기술 공유, 공개 연설, 강의용으로 적합합니다.",
    "de": "Spezielles Präsentationsdeck mit tokyo-night Standardthema, 5 Themes (T-Taste zum Wechseln), 150-300 Wörter Sprechernotizen pro Folie (<aside class=\"notes\">), S-Taste öffnet Popup (CURRENT / NEXT / SCRIPT / TIMER Karten). Ideal für technische Vorträge und Präsentationen mit Teleprompter-Funktion.",
    "fr": "Deck mode présentateur avec thème tokyo-night par défaut, 5 thèmes (touche T pour basculer), notes de 150-300 mots par diapo (<aside class=\"notes\">), touche S pour ouvrir popup (cartes CURRENT / NEXT / SCRIPT / TIMER). Parfait pour présentations techniques avec prompteur.",
    "ru": "Презентационная колода с темой tokyo-night по умолчанию, 5 тем (переключение клавишей T), заметки спикера на 150-300 слов (<aside class=\"notes\">), клавиша S открывает popup (карточки CURRENT / NEXT / SCRIPT / TIMER). Для технических докладов и презентаций с суфлером.",
    "es": "Deck modo presentador con tema tokyo-night predeterminado, 5 temas (tecla T para cambiar), notas de 150-300 palabras por diapositiva (<aside class=\"notes\">), tecla S abre popup (tarjetas CURRENT / NEXT / SCRIPT / TIMER). Ideal para charlas técnicas con teleprompter.",
    "pt-BR": "Deck modo apresentador com tema tokyo-night padrão, 5 temas (tecla T para alternar), notas de 150-300 palavras por slide (<aside class=\"notes\">), tecla S abre popup (cartões CURRENT / NEXT / SCRIPT / TIMER). Perfeito para palestras técnicas com teleprompter.",
    "it": "Deck modalità relatore con tema tokyo-night predefinito, 5 temi (tasto T per cambiare), note da 150-300 parole per slide (<aside class=\"notes\">), tasto S apre popup (schede CURRENT / NEXT / SCRIPT / TIMER). Ideale per presentazioni tecniche con teleprompter.",
    "vi": "Bộ slide chế độ diễn giả với chủ đề tokyo-night mặc định, 5 chủ đề (phím T để chuyển), ghi chú 150-300 từ mỗi slide (<aside class=\"notes\">), phím S mở popup (thẻ CURRENT / NEXT / SCRIPT / TIMER). Lý tưởng cho bài thuyết trình kỹ thuật với teleprompter.",
    "pl": "Pokład trybu prezentera z motywem tokyo-night, 5 motywów (klawisz T do przełączania), notatki 150-300 słów na slajd (<aside class=\"notes\">), klawisz S otwiera popup (karty CURRENT / NEXT / SCRIPT / TIMER). Idealny do prezentacji technicznych z teleprompterem.",
    "id": "Deck mode presenter dengan tema tokyo-night default, 5 tema (tombol T untuk ganti), catatan 150-300 kata per slide (<aside class=\"notes\">), tombol S buka popup (kartu CURRENT / NEXT / SCRIPT / TIMER). Cocok untuk presentasi teknis dengan teleprompter.",
    "nl": "Presentatormodus deck met tokyo-night standaardthema, 5 thema's (T-toets om te wisselen), 150-300 woorden notities per dia (<aside class=\"notes\">), S-toets opent popup (CURRENT / NEXT / SCRIPT / TIMER kaarten). Ideaal voor technische presentaties met autocue.",
    "ar": "مجموعة شرائح وضع المقدم مع سمة tokyo-night الافتراضية، 5 سمات (مفتاح T للتبديل)، ملاحظات 150-300 كلمة لكل شريحة (<aside class=\"notes\">)، مفتاح S يفتح popup (بطاقات CURRENT / NEXT / SCRIPT / TIMER). مثالي للعروض التقنية مع المطالبة.",
    "tr": "Sunucu modu destesi tokyo-night varsayılan teması, 5 tema (T tuşu ile değiştir), slayt başına 150-300 kelime notlar (<aside class=\"notes\">), S tuşu popup açar (CURRENT / NEXT / SCRIPT / TIMER kartları). Teknik sunumlar için teleprompter ile ideal.",
    "uk": "Презентаційна колода з темою tokyo-night за замовчуванням, 5 тем (клавіша T для перемикання), нотатки на 150-300 слів (<aside class=\"notes\">), клавіша S відкриває popup (картки CURRENT / NEXT / SCRIPT / TIMER). Для технічних доповідей з суфлером.",
    "en": "演讲者模式专用 deck — tokyo-night 默认主题，5 套主题 T 键切换，每页带 150-300 字逐字稿示例（<aside class=\"notes\">），按 S 打开 popup（CURRENT / NEXT / SCRIPT / TIMER 四张磁吸卡片）。用于技术分享、公开演讲、课程讲解，怕忘词或要提词器的场景。"
  },
